import{_ as t,o as l,c as o,ai as i}from"./chunks/framework.C33Uq6m-.js";const p=JSON.parse('{"title":"创建自定义测试集","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/benchmark-builder.md","filePath":"zh/guide/benchmark-builder.md"}'),n={name:"zh/guide/benchmark-builder.md"};function a(s,r,e,g,h,d){return l(),o("div",null,[...r[0]||(r[0]=[i('<h1 id="创建自定义测试集" tabindex="-1">创建自定义测试集 <a class="header-anchor" href="#创建自定义测试集" aria-label="Permalink to &quot;创建自定义测试集&quot;">​</a></h1><p>你可以创建自己的基准测试集，测试你真正关心的主题 —— 完全不需要手写 JSON。测试集构建器既支持手动编写题目，也可以让本地 AI 模型自动生成。</p><p><strong>侧边栏位置：</strong> 测试集构建器 <strong>路由：</strong> <code>/benchmark</code>（构建器标签页）</p><h2 id="手动录入题目" tabindex="-1">手动录入题目 <a class="header-anchor" href="#手动录入题目" aria-label="Permalink to &quot;手动录入题目&quot;">​</a></h2><p>完全手工构建一个测试集：</p><ol><li>打开<strong>基准测试</strong>页，点击<strong>构建器</strong>标签页。</li><li>填写<strong>测试集名称</strong>和可选的<strong>描述</strong>。</li><li>点击<strong>添加题目</strong>创建一个新条目。</li><li>填写<strong>题干</strong>。</li><li>添加<strong>选项</strong>（A、B、C、D）。如有需要可以增加更多选项。</li><li>从下拉框中选择<strong>正确答案</strong>。</li><li>可选：指定一个<strong>类别</strong>，用于按学科分组题目。</li><li>对每一道要添加的题目重复第 3–7 步。</li><li>完成后点击<strong>保存测试集</strong>。</li></ol><p>你的自定义测试集会与内置测试集并列出现，随时可以运行。</p><h2 id="ai-辅助生成" tabindex="-1">AI 辅助生成 <a class="header-anchor" href="#ai-辅助生成" aria-label="Permalink to &quot;AI 辅助生成&quot;">​</a></h2><p>让本地模型替你完成繁重的工作：</p><ol><li>在构建器标签页中，切换到 <strong>AI 生成</strong>区域。</li><li>输入一个<strong>主题</strong> —— 例如「法国大革命」「TCP/IP 网络」或「有机化学」。</li><li>选择要生成的<strong>题目数量</strong>。</li><li>选择<strong>难度</strong>（简单、中等、困难）。</li><li>从下拉框中选择负责生成题目的<strong>模型</strong>。</li><li>点击<strong>生成</strong>。模型会实时流式产出题目。</li></ol><p>生成完成后：</p><ul><li><strong>审阅</strong>每道题的准确性。</li><li><strong>编辑</strong>需要修正的题干、选项或正确答案。</li><li><strong>取消勾选</strong>格式不佳或有错误的题目 —— 它们不会被纳入。</li><li>点击<strong>加入测试集</strong>，把通过审阅的题目合并进你的测试集。</li></ul><h2 id="编辑测试集" tabindex="-1">编辑测试集 <a class="header-anchor" href="#编辑测试集" aria-label="Permalink to &quot;编辑测试集&quot;">​</a></h2><p>点击任意自定义测试集上的<strong>编辑</strong>按钮即可修改。你可以：</p><ul><li>重命名测试集或更新描述</li><li>添加、删除或重新排序题目</li><li>编辑单道题的题干、选项和正确答案</li><li>更改题目类别</li></ul><p>内置测试集（ARC、GSM8K 等）不可编辑，但你可以复制一份来创建修改版本。</p><h2 id="导出" tabindex="-1">导出 <a class="header-anchor" href="#导出" aria-label="Permalink to &quot;导出&quot;">​</a></h2><p>点击自定义测试集上的<strong>导出</strong>按钮，可将其下载为 <strong>JSON</strong> 文件。导出内容包含：</p><ul><li>测试集名称与描述</li><li>全部题目及其选项、正确答案索引和类别</li></ul><p>你可以把导出的 JSON 文件分享给他人，或贡献到<a href="/llmxray/docs/en/community/benchmarks.html">社区测试集</a>合集中。</p>',20)])])}const u=t(n,[["render",a]]);export{p as __pageData,u as default};
